  const providerNames=['ChatGPT-Konto','OpenAI API','Claude API','DeepSeek API'];
  for(const name of providerNames){const source=`Sprache und Dokumenttyp werden automatisch erkannt. Daten erscheinen als TT.MM.JJJJ. PDF mit Originalseiten, Word mit bearbeitbarer Übersetzung. Beim Übersetzen werden Dateien an ${name} gesendet.`;dictionaries.en[source]=`Language and document type are detected automatically. Dates use DD.MM.YYYY. The PDF includes the source pages; Word contains the editable translation. Files are sent to ${name==='ChatGPT-Konto'?'your ChatGPT account':name} when you translate.`;dictionaries.ar[source]=`يُكتشف نوع المستند ولغته تلقائياً. يُعرض التاريخ بصيغة يوم.شهر.سنة. يتضمن PDF الصفحات الأصلية، ويحتوي Word على الترجمة القابلة للتحرير. عند الترجمة، تُرسل الملفات إلى ${name==='ChatGPT-Konto'?'حساب ChatGPT الخاص بك':name}.`;}
