  Object.assign(dictionaries.ar,{"Übersetzungseinstellungen":"إعدادات الترجمة","KI-Anbieter":"مزود الذكاء الاصطناعي","KI-Einstellungen öffnen":"فتح إعدادات الذكاء الاصطناعي","Wird automatisch erkannt":"يُكتشف تلقائياً","Stilbeispiele verwalten":"إدارة أمثلة الأسلوب","Dateien auswählen":"إضافة ملفات","PDF, Word, Bilder und Text · bis zu 10 Dateien · 20 MB je Datei · 35 MB insgesamt":"PDF وWord والصور والنصوص · حتى 10 ملفات · 20 ميغابايت لكل ملف · 35 ميغابايت إجمالاً","Mehrere Dateien bilden einen Auftrag.":"تشكّل الملفات المتعددة مهمة واحدة.","Unterstützte Formate":"التنسيقات المدعومة","PDF, DOC, DOCX, ODT, RTF, TXT, MD, JPG, JPEG, PNG, WEBP, GIF, TIF, TIFF, BMP, HEIC, HEIF und AVIF.":"PDF وDOC وDOCX وODT وRTF وTXT وMD وJPG وJPEG وPNG وWEBP وGIF وTIF وTIFF وBMP وHEIC وHEIF وAVIF.",'Als unleserlich übernommen.':'تم التأكيد أنه غير مقروء.'});
  const introText={
    en:{skip:'Skip tour',back:'Back',next:'Continue',finish:'Start translating',demo:'Open demo',eyebrow:'Your workspace',askName:'What should Foliquo call you?',namePlaceholder:'Your name',language:'Preferred language',steps:[['Your workspace','Translate documents in one clear place.','Add documents, choose your model, and download the finished files from one private workspace.'],['1 · Add documents','Keep every side together.','Upload images, PDFs, and Word files. Add front and back pages to one job and include notes such as a passport spelling.'],['2 · Choose a model','Use the account or provider you prefer.','Sign in with your ChatGPT account, or connect an OpenAI, Claude, or DeepSeek API key. Source language and document type are detected automatically.'],['3 · Teach your style','Add translations that show your preferred result.','Upload finished Word or PDF translations in Learn style. Foliquo derives reusable layout and wording preferences; it does not copy personal facts.'],['4 · Edit if you want','Change the translation in its own chat.','Answer questions raised before translation, compare the source, and request edits. Field-by-field checks remain optional. Download PDF or Word whenever you are ready.'],['Try the demo','See a complete example first.','Open the guided demo with fictional documents, or skip the tour and start translating now. You can return to the demo from the workspace at any time.']]},
    de:{skip:'Tour überspringen',back:'Zurück',next:'Weiter',finish:'Übersetzen starten',demo:'Demo ansehen',eyebrow:'Dein Arbeitsplatz',askName:'Wie soll Foliquo dich nennen?',namePlaceholder:'Dein Name',language:'Bevorzugte Sprache',steps:[['Dein Arbeitsplatz','Dokumente an einem Ort übersetzen.','Füge Dokumente hinzu, wähle dein Modell und lade fertige Dateien aus einem privaten Arbeitsbereich herunter.'],['1 · Dokumente hinzufügen','Alle Seiten gemeinsam bearbeiten.','Lade Bilder, PDFs und Word-Dateien hoch. Vorder- und Rückseite gehören in einen Auftrag. Ergänze Hinweise wie eine Passschreibweise.'],['2 · Modell wählen','Nutze dein bevorzugtes Konto oder Modell.','Melde dich mit deinem ChatGPT-Konto an oder verbinde einen API-Schlüssel von OpenAI, Claude oder DeepSeek. Ausgangssprache und Dokumenttyp werden automatisch erkannt.'],['3 · Deinen Stil anlernen','Zeige Foliquo Beispiele für dein Wunschergebnis.','Lade fertige Word- oder PDF-Übersetzungen im Tab Anlernen hoch. Foliquo leitet wiederverwendbares Layout und Formulierungen ab, übernimmt aber keine Personendaten.'],['4 · Bearbeiten, wenn du möchtest','Änderungen im eigenen Chat anfordern.','Beantworte Rückfragen vor der Übersetzung, vergleiche das Original und bitte um Änderungen. Feldprüfungen sind optional. PDF oder Word kannst du jederzeit herunterladen.'],['Demo ausprobieren','Erst ein vollständiges Beispiel ansehen.','Öffne die geführte Demo mit fiktiven Dokumenten oder überspringe die Tour und beginne direkt. Die Demo bleibt jederzeit im Arbeitsbereich erreichbar.']]},
    ar:{skip:'تخطي الجولة',back:'رجوع',next:'متابعة',finish:'ابدأ الترجمة',demo:'عرض توضيحي',eyebrow:'مساحة عملك',askName:'كيف يناديك Foliquo؟',namePlaceholder:'اسمك',language:'اللغة المفضلة',steps:[['مساحة عملك','ترجم المستندات في مكان واحد واضح.','أضف المستندات واختر النموذج ونزّل الملفات النهائية من مساحة عمل خاصة.'],['١ · أضف المستندات','اجمع كل الصفحات معاً.','ارفع الصور وملفات PDF وWord. اجمع الوجهين في مهمة واحدة وأضف ملاحظات مثل تهجئة الاسم في جواز السفر.'],['٢ · اختر النموذج','استخدم الحساب أو المزوّد الذي تفضّله.','سجّل الدخول بحساب ChatGPT الخاص بك أو اربط مفتاح API لـ OpenAI أو Claude أو DeepSeek. تُكتشف اللغة الأصلية ونوع المستند تلقائياً.'],['٣ · علّم Foliquo أسلوبك','أضف ترجمات توضّح النتيجة التي تفضّلها.','ارفع ترجمات Word أو PDF منتهية في تبويب التعلّم. يستنتج Foliquo تنسيقاً وصياغات قابلة لإعادة الاستخدام دون نسخ البيانات الشخصية.'],['٤ · عدّل عند الحاجة','اطلب تعديلات في محادثة مستقلة.','أجب عن الأسئلة قبل الترجمة وقارن الأصل واطلب تعديلات. مراجعة كل حقل اختيارية. نزّل PDF أو Word متى شئت.'],['جرّب العرض التوضيحي','شاهد مثالاً كاملاً أولاً.','افتح العرض الإرشادي بمستندات خيالية، أو تخطّ الجولة وابدأ الترجمة. يمكنك العودة إلى العرض من مساحة العمل في أي وقت.']]}
  };
  Object.assign(dictionaries.ar,{"Übersetzungseinstellungen":"إعدادات الترجمة","KI-Anbieter":"مزود الذكاء الاصطناعي","KI-Einstellungen öffnen":"فتح إعدادات الذكاء الاصطناعي","Wird automatisch erkannt":"يُكتشف تلقائياً","Stilbeispiele verwalten":"إدارة أمثلة الأسلوب","Dateien auswählen":"إضافة ملفات","PDF, Word, Bilder und Text · bis zu 10 Dateien · 20 MB je Datei · 35 MB insgesamt":"PDF وWord والصور والنصوص · حتى 10 ملفات · 20 ميغابايت لكل ملف · 35 ميغابايت إجمالاً","Mehrere Dateien bilden einen Auftrag.":"تشكّل الملفات المتعددة مهمة واحدة.","Unterstützte Formate":"التنسيقات المدعومة","PDF, DOC, DOCX, ODT, RTF, TXT, MD, JPG, JPEG, PNG, WEBP, GIF, TIF, TIFF, BMP, HEIC, HEIF und AVIF.":"PDF وDOC وDOCX وODT وRTF وTXT وMD وJPG وJPEG وPNG وWEBP وGIF وTIF وTIFF وBMP وHEIC وHEIF وAVIF.",'Anlernen':'التعلّم','Dokumente übersetzen und als PDF oder Word speichern.':'ترجم المستندات واحفظها بصيغة PDF أو Word.','Lade fertige Übersetzungen hoch. Foliquo übernimmt daraus wiederkehrenden Aufbau und Formulierungsstil.':'ارفع ترجمات مكتملة ليستنتج Foliquo التنسيق والصياغات المتكررة.','Fertige Übersetzung hinzufügen':'إضافة ترجمة مكتملة','Privat gespeichert':'محفوظة بخصوصية','Word, PDF oder ein Bild genügt. Foliquo erkennt Sprache, Dokumenttyp, Aufbau und wiederverwendbare Formulierungen automatisch.':'ارفع ملف Word أو PDF أو صورة. يكتشف Foliquo اللغة ونوع المستند والتنسيق والصياغات القابلة لإعادة الاستخدام تلقائياً.','Datei auswählen':'اختيار ملفات','Bilder · bis zu 20 MB':'صور · حتى ٢٠ ميغابايت','Was Foliquo übernimmt':'ما الذي يتعلّمه Foliquo','Dokumente ansehen':'قراءة المستندات','Nur die von dir hochgeladenen Beispiele werden ausgewertet.':'يحلّل الأمثلة التي ترفعها فقط.','Stil erkennen':'تعلّم الأسلوب','Aufbau, Feldreihenfolge, Schriftbild und wiederkehrende Formulierungen.':'التنسيق وترتيب الحقول والخط والصياغات المتكررة.','Bei passenden Aufträgen anwenden':'استخدامه في المهام المشابهة','Deine Originalangaben bleiben maßgeblich. Personenbezogene Daten aus Mustern werden nicht übernommen.':'يبقى المستند الأصلي هو المرجع. لا تُنسخ البيانات الشخصية من الأمثلة.','Deine Muster':'أمثلتك','Hier erscheinen deine hochgeladenen Übersetzungen.':'ستظهر الترجمات التي رفعتها هنا.','Muster ansehen':'معاينة المثال','Vorschau schließen':'إغلاق المعاينة','Entfernen':'إزالة','Anwenden':'استخدام في مهام جديدة','Speicher, Sicherung und Aufbewahrung':'التخزين والنسخ الاحتياطي ومدة الاحتفاظ','Die aktuelle Fassung ist bereit.':'النسخة الحالية جاهزة.','Detailprüfung und Chatbearbeitung sind optional.':'المراجعة التفصيلية والتعديل عبر المحادثة اختياريان.','PDF und Word herunterladen':'تنزيل PDF وWord','PDF herunterladen ↓':'تنزيل PDF ↓','Word herunterladen ↓':'تنزيل Word ↓','PDF + Word herunterladen ↓':'تنزيل PDF وWord ↓','Prüffelder und Detailkontrolle · optional':'الحقول والمراجعة التفصيلية · اختياري','Demo ansehen':'عرض توضيحي','Übersetzung starten':'ابدأ الترجمة','Übersetzen':'ترجمة','Übersetzen.':'ترجمة.','Dokument hochladen. Sprache und Dokumenttyp erkennt Foliquo automatisch.':'ارفع مستنداً. يتعرّف Foliquo تلقائياً على اللغة ونوع المستند.','KI-Verbindung':'اتصال الذكاء الاصطناعي','Mit ChatGPT anmelden oder einen API-Anbieter verbinden.':'سجّل الدخول عبر ChatGPT أو اربط مزوّد ذكاء اصطناعي.','Herunterladen':'تنزيل','PDF + Word':'PDF وWord'});
